// Exact file names win over extensions.
const BY_NAME = {
  'package.json': 'npm', 'package-lock.json': 'npm', 'pnpm-lock.yaml': 'npm', '.npmrc': 'npm', '.npmignore': 'npm',
  'yarn.lock': 'yarn', '.yarnrc': 'yarn', '.yarnrc.yml': 'yarn',
  '.gitignore': 'git', '.gitattributes': 'git', '.gitmodules': 'git', '.gitkeep': 'git', '.mailmap': 'git',
  'readme': 'readme', 'readme.md': 'readme', 'readme.txt': 'readme', 'readme.rst': 'readme',
  'changelog': 'changelog', 'changelog.md': 'changelog', 'history.md': 'changelog',
  'license': 'document', 'license.md': 'document', 'licence': 'document', 'notice': 'document',
  'dockerfile': 'docker', 'docker-compose.yml': 'docker', 'docker-compose.yaml': 'docker', '.dockerignore': 'docker',
  'makefile': 'makefile', 'gnumakefile': 'makefile', 'cmakelists.txt': 'makefile',
  '.editorconfig': 'editorconfig', '.travis.yml': 'travis',
  'gemfile': 'gemfile', 'gemfile.lock': 'gemfile', '.ruby-version': 'gemfile',
  'cargo.toml': 'rust', 'cargo.lock': 'rust',
  'go.mod': 'go', 'go.sum': 'go',
  '.nvmrc': 'nodejs', '.node-version': 'nodejs',
  'todo': 'todo', 'todo.md': 'todo',
}

// Prefix matches, for the config files that come in a dozen spellings.
const BY_PREFIX = [
  ['.eslint', 'eslint'], ['eslint.config', 'eslint'],
  ['.prettier', 'prettier'], ['prettier.config', 'prettier'],
  ['.babelrc', 'babel'], ['babel.config', 'babel'],
  ['webpack.config', 'webpack'], ['rollup.config', 'rollup'],
  ['tsconfig', 'typescript'], ['jsconfig', 'javascript'],
  ['.env', 'settings'],
]

const BY_EXTENSION = {
  js: 'javascript', mjs: 'javascript', cjs: 'javascript', jsx: 'react',
  ts: 'typescript', mts: 'typescript', cts: 'typescript', tsx: 'react',
  json: 'json', json5: 'json', jsonc: 'json',
  html: 'html', htm: 'html', ejs: 'html', hbs: 'html',
  css: 'css3', scss: 'sass', sass: 'sass', less: 'less', vue: 'vue',
  md: 'markdown', markdown: 'markdown', mdx: 'mdx', rst: 'markdown',
  py: 'python', pyw: 'python', pyi: 'python',
  rb: 'ruby', go: 'go', rs: 'rust', jar: 'java', java: 'java',
  kt: 'kotlin', kts: 'kotlin', swift: 'swift',
  c: 'c', h: 'h', cpp: 'cpp', cc: 'cpp', cxx: 'cpp', hpp: 'hpp', hh: 'hpp', hxx: 'hpp',
  cs: 'csharp', php: 'php', lua: 'lua', pl: 'perl', pm: 'perl', r: 'r', dart: 'dart',
  ex: 'elixir', exs: 'elixir', erl: 'erlang', hrl: 'erlang', hs: 'haskell',
  scala: 'scala', sbt: 'scala', clj: 'clojure', cljs: 'clojure', edn: 'clojure',
  sol: 'solidity', wasm: 'webassembly', wat: 'webassembly',
  sh: 'console', bash: 'console', zsh: 'console', fish: 'console', bat: 'console', cmd: 'console',
  ps1: 'powershell', psm1: 'powershell', psd1: 'powershell',
  sql: 'database', db: 'database', sqlite: 'database', sqlite3: 'database',
  tf: 'terraform', tfvars: 'terraform', ipynb: 'jupyter', tex: 'tex', bib: 'tex',
  yml: 'yaml', yaml: 'yaml',
  xml: 'xml', xsd: 'xml', xsl: 'xml', plist: 'xml', svg: 'image',
  graphql: 'graphql', gql: 'graphql',
  toml: 'settings', ini: 'settings', cfg: 'settings', conf: 'settings', properties: 'settings',
  lock: 'lock', txt: 'document', rtf: 'document', pdf: 'pdf',
  csv: 'table', tsv: 'table',
  xls: 'microsoft-excel', xlsx: 'microsoft-excel',
  doc: 'microsoft-word', docx: 'microsoft-word',
  ppt: 'microsoft-powerpoint', pptx: 'microsoft-powerpoint',
  png: 'image', jpg: 'image', jpeg: 'image', gif: 'image', webp: 'image',
  bmp: 'image', ico: 'image', avif: 'image', tif: 'image', tiff: 'image', psd: 'image',
  mp3: 'audio', wav: 'audio', ogg: 'audio', flac: 'audio', m4a: 'audio', aac: 'audio',
  mp4: 'video', mov: 'video', avi: 'video', mkv: 'video', webm: 'video', wmv: 'video',
  zip: 'zip', tar: 'zip', gz: 'zip', tgz: 'zip', rar: 'zip', '7z': 'zip', bz2: 'zip', xz: 'zip',
  exe: 'exe', msi: 'exe', dll: 'exe', dmg: 'exe', deb: 'exe', rpm: 'exe', appimage: 'exe',
  ttf: 'font', otf: 'font', woff: 'font', woff2: 'font', eot: 'font',
  log: 'log', diff: 'diff', patch: 'diff',
  key: 'key', pem: 'key', pfx: 'key', p12: 'key',
  crt: 'certificate', cer: 'certificate', cert: 'certificate',
}

export function iconNameForFile(filePath) {
  const name = String(filePath).replaceAll('\\', '/').split('/').pop().toLowerCase()
  if (BY_NAME[name]) return BY_NAME[name]
  const prefixed = BY_PREFIX.find(([prefix]) => name.startsWith(prefix))
  if (prefixed) return prefixed[1]
  const dot = name.lastIndexOf('.')
  return (dot > 0 && BY_EXTENSION[name.slice(dot + 1)]) || 'file'
}

export default function FileIcon({ path, className = 'file-icon' }) {
  const [viewBox, body] = ICONS[iconNameForFile(path)] || ICONS.file
  return <svg className={className} viewBox={viewBox} aria-hidden="true" focusable="false" dangerouslySetInnerHTML={{ __html: body }} />
}
